def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] != bg:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            y0 = min(y for y, x in cells)
            y1 = max(y for y, x in cells)
            x0 = min(x for y, x in cells)
            x1 = max(x for y, x in cells)
            border = {(y, x) for y, x in cells}
            if y1 - y0 < 2 or x1 - x0 < 2:
                continue
            expected = {(y, x) for y in range(y0, y1 + 1) for x in range(x0, x1 + 1)
                        if y in (y0, y1) or x in (x0, x1)}
            if border != expected or any(grid[y][x] != color for y, x in expected):
                continue
            fill = 7 if (y1 - y0 - 1) % 2 == 1 else 2
            for y in range(y0 + 1, y1):
                for x in range(x0 + 1, x1):
                    out[y][x] = fill
    return out
